/*
 * prog22_snake_camel_convert.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * from the obfuscated binary.  The program expects exactly two command line
 * arguments:
 *
 *   1. a mode string – either "to_camel" or "to_snake"
 *   2. the input string to be converted
 *
 * If the argument count is insufficient the program prints "USAGE".
 * If the mode string is not recognised it prints "INVALID_MODE".
 *
 * Conversion rules (derived from the original binary):
 *
 *   to_camel : snake_case → camelCase
 *               – every '_' is removed
 *               – the character following an '_' is upper‑cased
 *               – all other alphabetic characters are lower‑cased
 *
 *   to_snake : camelCase → snake_case
 *               – an '_' is inserted before each upper‑case letter
 *               – the upper‑case letter itself is lower‑cased
 *               – all other characters are copied unchanged
 *
 * The output is written into a static buffer of size 0x400 (1024) bytes,
 * matching the original binary, and printed with puts().
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024   /* 0x400 bytes – same as the original binary */

int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------- */
    /* Argument count check – the original printed "USAGE" when fewer */
    /* than three arguments (program name + 2).                        */
    /* --------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];
    char out[OUT_BUF_SIZE];
    size_t out_len = 0;

    /* --------------------------------------------------------------- */
    /* to_camel : snake_case → camelCase                               */
    /* --------------------------------------------------------------- */
    if (strcmp(mode, "to_camel") == 0) {
        int capitalize_next = 0;               /* flag set after '_' */
        for (size_t i = 0; input[i] != '\0'; ++i) {
            unsigned char ch = (unsigned char)input[i];

            if (ch == '_') {                   /* skip '_' and set flag   */
                capitalize_next = 1;
                continue;
            }

            if (capitalize_next) {
                out[out_len++] = (char)toupper(ch);
                capitalize_next = 0;
            } else {
                out[out_len++] = (char)tolower(ch);
            }

            if (out_len >= OUT_BUF_SIZE - 1)   /* safety – mimic original */
                break;
        }
        out[out_len] = '\0';
        puts(out);
        return 0;
    }

    /* --------------------------------------------------------------- */
    /* to_snake : camelCase → snake_case                               */
    /* --------------------------------------------------------------- */
    if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] != '\0'; ++i) {
            unsigned char ch = (unsigned char)input[i];

            if (isupper(ch)) {
                /* Insert '_' before an upper‑case letter unless it would
                   overflow the buffer or be the very first character. */
                if (out_len > 0 && out_len < OUT_BUF_SIZE - 2) {
                    out[out_len++] = '_';
                }
                out[out_len++] = (char)tolower(ch);
            } else {
                out[out_len++] = (char)ch;
            }

            if (out_len >= OUT_BUF_SIZE - 1)   /* safety – mimic original */
                break;
        }
        out[out_len] = '\0';
        puts(out);
        return 0;
    }

    /* --------------------------------------------------------------- */
    /* Any other mode string – the original printed "INVALID_MODE".   */
    /* --------------------------------------------------------------- */
    puts("INVALID_MODE");
    return 0;
}
